export type Binding = `${'plugin'|'input'|'config'|'ui'|'run'|'stats'|'row'}.${string}`;
export type Predicate = { path: Binding; op: 'eq'|'ne'|'truthy'|'falsy'; value?: string|number|boolean|null };
export type Event = 'start'|'newRun'|'refresh'|'cancelRun'|'retry'|'editDraft'|'cancelTask'|'openTab'|'clearSelection'|'confirmDrafts';
export type Tone = 'default'|'muted'|'primary'|'success'|'warning'|'danger';
export type ComponentProps = {
  Page: {title?:string;description?:string}; Stack: {direction?:'row'|'column';gap?:'none'|'sm'|'md'|'lg'};
  Grid: {columns?:1|2|3|4;ratio?:'equal'|'wide-left';gap?:'none'|'sm'|'md'|'lg'};
  Card: {title?:string;description?:string};
  Text: {text?:string;bind?:Binding;tone?:Tone;size?:'sm'|'md'|'lg'|'xl';lines?:1|2|3;format?:'text'|'datetime'|'mediaType'|'defaultSeason'};
  Badge: {text?:string;bind?:Binding;tone?:Tone}; Alert: {text?:string;bind?:Binding;tone?:Tone};
  Input: {label?:string;bind?:Binding;placeholder?:string;type?:'text'|'number'};
  Textarea: {label?:string;bind?:Binding;placeholder?:string}; Select: {label?:string;bind?:Binding;options?:{label:string;value:string|number|boolean}[]};
  Checkbox:{label?:string;bind?:Binding}; FilePicker:Record<string,never>; ProfilePicker:{label?:string;bind?:Binding};
  Steps:{labels?:string[];bind?:Binding}; Metric:{label?:string;bind?:Binding;tone?:Tone;filter?:'all'|'ready'|'needs_review'|'submitted'};
  Progress:{label?:string;bind?:Binding;total?:Binding}; Results:{title?:string};
  Table:{source?:'run.drafts'|'run.result';columns?:TableColumn[];selectable?:boolean;selectionBind?:Binding;rowKey?:Binding}; Details:{label?:string};
  Button:{label?:string;action:Event;actionId?:string;tab?:TabID;variant?:'default'|'outline'|'secondary'|'ghost'|'destructive'};
  Status:{bind?:Binding}; EmptyState:{title?:string;description?:string}; Search:{placeholder?:string};
  Pagination:Record<string,never>; SelectionBar:Record<string,never>; RunHistory:Record<string,never>; ConfigForm:Record<string,never>; ScheduleForm:Record<string,never>; RunLog:Record<string,never>; TaskList:Record<string,never>; DataManagement:Record<string,never>;
};
export type Component = keyof ComponentProps;
export type UINode = {[C in Component]:{component:C;props?:ComponentProps[C];children?:UINode[];visibleWhen?:Predicate;disabledWhen?:Predicate}}[Component];
export type TableColumn = {label:string;cells:UINode[]};
export type TabID = 'overview'|'run'|'history'|'settings';
export type UIPage = {version:'1';tabs:{id:TabID;label:string;content:UINode[]}[]};
export function node<C extends Component>(component:C,props?:ComponentProps[C],children?:UINode[]):UINode;
export function definePage(page:UIPage):UIPage;
export function validatePage(page:unknown,actions?:string[]):UIPage;
export function resolve(model:unknown,path:string):unknown;
export function matches(model:unknown,predicate?:Predicate):boolean;
export const registry:unknown;
